import{_ as a,o as n,c as i,j as t}from"./chunks/framework.DsyGq6Zh.js";const m=JSON.parse('{"title":"Research in Evidence-Governed AI Systems","description":"Research agenda, engineering case studies, working papers, prior art, and a preliminary doctoral proposal by Keith Williams.","frontmatter":{"title":"Research in Evidence-Governed AI Systems","description":"Research agenda, engineering case studies, working papers, prior art, and a preliminary doctoral proposal by Keith Williams."},"headers":[],"relativePath":"research/systems/index.md","filePath":"research/systems/index.md"}'),s={name:"research/systems/index.md"};function r(o,e,d,c,l,h){return n(),i("div",null,[...e[0]||(e[0]=[t('<h1 id="evidence-governed-ai-systems" tabindex="-1">Evidence-Governed AI Systems <a class="header-anchor" href="#evidence-governed-ai-systems" aria-label="Permalink to &quot;Evidence-Governed AI Systems&quot;">​</a></h1><p><strong>How can we turn unstructured information into useful, personalized knowledge artifacts while preserving evidence, authority, and the scarce attention of human experts?</strong></p><p>This is my developing research program. It grew out of building software and exploring the limits of AI-assisted development. The articles distinguish <em>implemented systems</em>, <em>documented design proposals</em>, and <em>hypotheses not yet tested in controlled studies</em>. They are not peer-reviewed publications.</p><h2 id="a-connected-research-vision" tabindex="-1">A connected research vision <a class="header-anchor" href="#a-connected-research-vision" aria-label="Permalink to &quot;A connected research vision&quot;">​</a></h2><p><strong><a href="./vision-and-interface">From claims to navigable knowledge</a></strong> connects the full experience: evidence-backed claims as the canonical knowledge model; distinct page-navigation and evidentiary graphs; Wikipedia/Wikidata as attributed discovery sources; semantic search; dynamically rendered dossiers; and a decision-oriented intelligence briefing with original-citation drill-down.</p><p><strong><a href="./uap-research-testbed">Why UAP records are an unusually demanding testbed</a></strong> explains exactly what the case can and cannot demonstrate, what source acquisition remains to be done, and why a second independently labeled benchmark is essential.</p><h2 id="the-research-in-one-view" tabindex="-1">The research in one view <a class="header-anchor" href="#the-research-in-one-view" aria-label="Permalink to &quot;The research in one view&quot;">​</a></h2><ul><li><strong>Knowledge:</strong> acquire multimodal material, construct claims and relationships, and retain access to exact sources, contradictory evidence, and uncertainty.</li><li><strong>Orchestration:</strong> use self-describing sensors, deterministic tools, local/frontier models, and authorized reviewers to process work appropriately.</li><li><strong>Governance:</strong> distinguish observations from qualified knowledge; record what was approved, by whom, under which policy and evidence.</li><li><strong>Economics:</strong> spend expensive human judgment on decisions where it changes the outcome; measure errors, recovery, compute, and review time.</li><li><strong>Outcomes:</strong> generate reliable personalized educational, business, and media artifacts from qualified knowledge.</li></ul><h2 id="essays-and-technical-case-studies" tabindex="-1">Essays and technical case studies <a class="header-anchor" href="#essays-and-technical-case-studies" aria-label="Permalink to &quot;Essays and technical case studies&quot;">​</a></h2><ol><li><a href="./personalized-knowledge-artifacts">Why I started with personalized knowledge artifacts</a> — motivation, timeline and product objective.</li><li><a href="./metavis-evidence-and-evaluation">MetaVis: tests, sensors and qualitative AI evaluation</a> — Swift/Metal engineering case study.</li><li><a href="./race-track-pit-stop">The Race Track and the Pit Stop</a> — risk-based review and commissioning.</li><li><a href="./provenance-knowledge-graphs">Building qualified knowledge from contradictory sources</a> — graph/vector retrieval and the UAP corpus.</li><li><a href="./english-software-engineering">English as a software engineering abstraction</a> — instructions, contracts, tests and human–AI collaboration.</li><li><a href="./human-attention-kanban">Human attention as an engineering constraint</a> — resource allocation, Kanban and economics.</li></ol><h2 id="academic-documents" tabindex="-1">Academic documents <a class="header-anchor" href="#academic-documents" aria-label="Permalink to &quot;Academic documents&quot;">​</a></h2><ul><li><a href="./dissertation-proposal">Preliminary dissertation proposal</a> — advisor discussion draft, not an approved proposal.</li><li><a href="./literature-and-faculty">Related research and NJIT faculty reading map</a> — a selective, sourced starting bibliography, including five NJIT faculty research connections.</li></ul><h2 id="implemented-evidence-versus-proposals" tabindex="-1">Implemented evidence versus proposals <a class="header-anchor" href="#implemented-evidence-versus-proposals" aria-label="Permalink to &quot;Implemented evidence versus proposals&quot;">​</a></h2><p><strong>Implemented evidence:</strong> <a href="https://github.com/kaw393939/chunky-monkey-text-chunker" target="_blank" rel="noreferrer">Chunky Monkey</a> (document processing), <a href="https://github.com/kaw393939/metavis-demo-projects" target="_blank" rel="noreferrer">MetaVis</a> (Swift/Metal pipeline, sensors and QA code), Ordo Executor (private research prototype) (composable ingestion and candidate-promotion contracts).</p><p><strong>Design and investigation:</strong> <a href="https://github.com/kaw393939/ordo" target="_blank" rel="noreferrer">Ordo</a> (business appliance doctrine, governance and a runtime that its README says has not started), UAP Corpus (private research catalog) (38 curated metadata records and acquisition design; source files not yet downloaded).</p><p><strong>Open research question:</strong> no controlled evaluation has yet established the reliability, navigability or economic advantage of the full proposed architecture. This site presents that as a hypothesis worth testing, not a result.</p><p><em>Personal research work, November 2026. No institutional endorsement, approved doctorate, or completed dissertation is implied.</em></p>',17)])])}const u=a(s,[["render",r]]);export{m as __pageData,u as default};
